98: static void make_fixup(const kj_target *t, uint32_t vp, bool wbuffer, float f[4][4])
99: {
100:     const float x1 = (float)(vp & 0xFF), y1 = (float)((vp >> 8) & 0xFF);
101:     const float vw = (float)(((vp >> 16) & 0xFF)) - x1 + 1.0f;
102:     const float vh = (float)(((vp >> 24) & 0xFF)) - y1 + 1.0f;
103:     const float a = t->scale / 120.0f;
104:     const float half_w = t->width / 2.0f;
105:     const float b = t->scale / half_w;
106: 
107:     memset(f, 0, sizeof(float) * 16);
108:     f[0][1] = a * vh / 2.0f;
109:     f[0][3] = 1.0f - a * (192.0f - y1 - vh / 2.0f);
110:     f[1][0] = -b * vw / 2.0f;
111:     f[1][3] = 1.0f - t->offset_x / half_w - b * (x1 + vw / 2.0f);
112:     if (wbuffer) {
113:         f[2][3] = -W_DEPTH_SCALE;
114:     } else {
115:         f[2][2] = 0.5f;
116:         f[2][3] = -0.5f;
117:     }
118:     f[3][3] = 1.0f;
119: }
