353: #endif
354: #ifndef HGSS_PROFILE_OFF
355:     s_stats.box_tests += f->box_tests;
356: #endif
357: #ifndef HGSS_PROFILE_OFF
358:     s_stats.box_culled += f->box_culled;
359: #endif
