388:     const unsigned alpha_ref = (f->disp3dcnt & 4u) ? f->alpha_test_ref : 0u;
389:     C3D_AlphaTest(!(kj_script_debug() & KJ_DEBUG_NO_ALPHA_TEST), GPU_GREATER,
390:                   (int)(alpha_ref * 255u / 31u));
391:     C3D_StencilTest(true, GPU_ALWAYS, stencil_flags, 0, 0x03);
392:     C3D_StencilOp(GPU_STENCIL_KEEP, GPU_STENCIL_KEEP, GPU_STENCIL_REPLACE);
