397:     C3D_DepthTest(false, GPU_ALWAYS, GPU_WRITE_COLOR);
398:     C3D_CullFace(GPU_CULL_NONE);
399:     kj_gpu_invalidate();
400:     kj_perf_add(KJ_PERF_G3D, kj_perf_now() - t0);
